package de.corporate.lc.training.api;
import de.corporate.lc.document.service.DocumentExtractionService;import de.corporate.lc.imports.api.*;import de.corporate.lc.imports.service.SwiftImportService;import de.corporate.lc.lc.domain.LetterOfCredit;import de.corporate.lc.swift.PrintedSwiftNormalizer;import de.corporate.lc.training.domain.TrainingSession;import de.corporate.lc.training.repository.TrainingSessionRepository;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.time.LocalDateTime;import java.util.*;
@RestController @RequestMapping("/api/training") public class TrainingController{private final TrainingSessionRepository repo;private final DocumentExtractionService extraction;private final PrintedSwiftNormalizer normalizer;private final SwiftImportService imports;public TrainingController(TrainingSessionRepository r,DocumentExtractionService e,PrintedSwiftNormalizer n,SwiftImportService i){repo=r;extraction=e;normalizer=n;imports=i;}@PostMapping("/preview")@Transactional public TrainingPreview preview(@RequestPart("file")MultipartFile file,Authentication auth)throws IOException{if(file.isEmpty()||file.getSize()>10*1024*1024)throw new IllegalArgumentException("PDF fehlt oder ist größer als 10 MB.");var x=extraction.extractFile(file.getBytes(),file.getOriginalFilename(),file.getContentType());String text=normalizer.normalize(x.text());if(text.isBlank())throw new IllegalArgumentException("Keine SWIFT-Felder erkannt.");var request=new SwiftImportRequest(file.getOriginalFilename(),text);var preview=imports.preview(request);TrainingSession s=new TrainingSession();s.setFilename(file.getOriginalFilename());s.setContentType(file.getContentType());s.setOriginalPdf(file.getBytes());s.setExtractedText(text);s.setStatus("DRAFT");s.setUsername(auth.getName());s.setExtractionStatus(x.status());s.setMessageType(preview.messageType());repo.save(s);return new TrainingPreview(s.getId(),request,preview,x.status());}@PostMapping("/{id}/confirm")@Transactional public Object confirm(@PathVariable UUID id,@RequestBody TrainingConfirm request,Authentication auth){TrainingSession s=repo.findById(id).orElseThrow();if(!s.getUsername().equals(auth.getName()))throw new IllegalArgumentException("Trainingssitzung gehört einem anderen Benutzer.");Object result=imports.execute(new SwiftImportRequest(s.getFilename(),request.correctedRawMessage()));s.setCorrectedText(request.correctedRawMessage());s.setReviewsJson(request.reviewsJson());s.setStatus("CONFIRMED");s.setConfirmedAt(LocalDateTime.now());if(result instanceof LetterOfCredit lc)s.setLcId(lc.getId());return result;}@GetMapping public List<TrainingView> history(){return repo.findTop100ByOrderByCreatedAtDesc().stream().map(s->new TrainingView(s.getId(),s.getFilename(),s.getStatus(),s.getUsername(),s.getMessageType(),s.getCreatedAt())).toList();}}
